function exportDebtorsToCSV() {
  const debtors = appState.clients
    .map(c => ({
      client: c,
      stats: getClientBalance(c.id)
    }))
    .filter(item => item.stats.balance > 0)
    .sort((a, b) => b.stats.balance - a.stats.balance);

  if (debtors.length === 0) {
