  }

  let csvContent = '\uFEFF';
  csvContent += 'No,Nombre,Referencia / Empresa,Telefono,Ultimo Consumo,Total Consumido,Total Abonado,Saldo Pendiente\n';

  debtors.forEach((item, index) => {
    const { client, stats } = item;
    const cleanName = `"${(client.name || '').replace(/"/g, '""')}"`;
    const cleanAlias = `"${(client.alias || '').replace(/"/g, '""')}"`;
    const cleanPhone = `"${(client.phone || '').replace(/"/g, '""')}"`;
    const lastDate = stats.lastCreditDate ? formatDate(stats.lastCreditDate) : 'N/A';

